using System;

// PROGRAM: Simulasi Siklus Hidup EntityState pada Change Tracker EF Core
public enum EntityState { Detached, Unchanged, Added, Deleted, Modified }

public class TrackedEntity<T>
{
    public T Current { get; set; }
    public T Snapshot { get; private set; }
    public EntityState State { get; set; }

    public TrackedEntity(T initialData)
    {
        Current = initialData;
        Snapshot = initialData;
        State = EntityState.Unchanged;
    }

    public void DetectChanges()
    {
        if (State == EntityState.Detached) return;

        if (!Current!.Equals(Snapshot))
        {
            State = EntityState.Modified;
            Console.WriteLine("[CHANGE TRACKER] Perubahan terdeteksi! Status berubah menjadi: MODIFIED.");
        }
        else
        {
            Console.WriteLine("[CHANGE TRACKER] Tidak ada perubahan nilai (UNCHANGED).");
        }
    }
}

public class Program
{
    public static void Main()
    {
        // Simulasi
        var tracker = new TrackedEntity<decimal>(1_000_000m);
        Console.WriteLine($"Status Awal: {tracker.State} (Saldo: Rp {tracker.Current:N0})");

        // Mutasi nilai
        tracker.Current = 1_500_000m;
        tracker.DetectChanges(); // Status menjadi Modified!
    }
}

