using System;

public class ChangeTrackerSimulator
{
    public static string DetectEntityState(decimal originalBalance, decimal currentBalance, bool isMarkedForDeletion, bool isNew)
    {
        if (isNew) return "Added";
        if (isMarkedForDeletion) return "Deleted";
        if (originalBalance != currentBalance) return "Modified";
        return "Unchanged";
    }

    public static void Main()
    {
        Console.WriteLine(DetectEntityState(100m, 100m, false, false));
        Console.WriteLine(DetectEntityState(100m, 200m, false, false));
        Console.WriteLine(DetectEntityState(100m, 100m, false, true));
    }
}
